%% TRAJ_EVAL LOG ANALYSIS
% Standalone post-processing for logs generated by main_dept_TRAJ_EVAL.m.
% It fits a line to the estimated trajectory, plots the result on the DEPT
% map, and computes statistical indicators against the ideal rectilinear
% reference segment.
%
% Metric set follows the evaluation style recurring in the local references:
% Euclidean positioning error, MAE/RMSE/SD/median/CDF percentiles, axis-wise
% bias and standard deviation, update-rate/latency, path straightness, and
% covariance scale diagnostics when EKF covariance is logged.

clearvars; clc; close all;

%% User configuration
script_dir = fileparts(mfilename('fullpath'));
if isempty(script_dir)
    script_dir = pwd;
end
project_root = fileparts(script_dir);

cfg = struct();
% Leave both empty to analyze the latest session in project_root/TRAJ_EVAL_logs.
cfg.session_dir = "";
cfg.samples_csv_path = "";

cfg.logs_root_dir = fullfile(project_root, "TRAJ_EVAL_logs");
cfg.map_csv_path = fullfile(script_dir, "DEPT_evb1000_map.csv");

% If true, regression/statistics discard points whose closest point is one
% of the reference-segment endpoints.
cfg.use_only_samples_projected_inside_segment = false;

% Optional trim along the ideal segment, useful to remove start/stop effects.
% Example: [0.05, 0.95] keeps the middle 90 percent of the ideal segment.
cfg.keep_rect_fraction_range = [0.0, 1.0];

cfg.plot_residual_segments_on_map = true;
cfg.max_residual_segments_on_map = 250;
cfg.save_outputs = true;

%% Load data and reference
[samples_csv_path, session_dir] = resolve_samples_csv_path(cfg);
samples = readtable(samples_csv_path);
if height(samples) < 2
    error("[traj_eval_analysis] Need at least two logged samples in %s", samples_csv_path);
end

reference = load_reference_definition(session_dir, samples);
anchors = load_dept_map_anchors(cfg.map_csv_path);
analysis_mask = build_analysis_mask(samples, cfg);

if nnz(analysis_mask) < 2
    error("[traj_eval_analysis] Less than two valid samples after filtering.");
end

analysis = analyze_trajectory(samples, analysis_mask, reference);
output_dir = session_dir;

%% Print and save indicators
fprintf("\n[traj_eval_analysis] session: %s\n", session_dir);
fprintf("[traj_eval_analysis] samples CSV: %s\n", samples_csv_path);
fprintf("[traj_eval_analysis] selected samples: %d / %d\n", analysis.sample_count, height(samples));
fprintf("[traj_eval_analysis] ideal nodes: %s\n", reference.label);
fprintf("[traj_eval_analysis] ideal length: %.3f m | heading: %.3f deg\n", ...
    reference.length_m, rad2deg(reference.heading_rad));
fprintf("[traj_eval_analysis] distance-to-ideal std=%.4f m | rmse=%.4f m | mae=%.4f m | p95=%.4f m\n", ...
    analysis.distance_to_segment_m.std, analysis.distance_to_segment_m.rmse, ...
    analysis.distance_to_segment_m.mae, analysis.distance_to_segment_m.p95);
fprintf("[traj_eval_analysis] signed cross-track bias=%.4f m | std=%.4f m\n", ...
    analysis.signed_cross_track_m.mean, analysis.signed_cross_track_m.std);
fprintf("[traj_eval_analysis] axis bias x/y=(%.4f, %.4f) m | axis std x/y=(%.4f, %.4f) m\n", ...
    analysis.error_x_m.mean, analysis.error_y_m.mean, ...
    analysis.error_x_m.std, analysis.error_y_m.std);
fprintf("[traj_eval_analysis] OLS %s: heading err=%.4f deg | R2=%.4f\n", ...
    char(analysis.ols.model), analysis.ols.heading_error_deg, analysis.ols.r2);
fprintf("[traj_eval_analysis] TLS orthogonal fit: heading err=%.4f deg | residual std=%.4f m\n\n", ...
    analysis.tls.heading_error_deg, analysis.tls.orthogonal_residual_m.std);
fprintf("[traj_eval_analysis] path straightness=%.4f | sinuosity=%.4f | update rate=%.3f Hz\n", ...
    analysis.path.straightness_ratio, analysis.path.sinuosity_ratio, analysis.timing.effective_update_rate_hz);
if analysis.covariance.available
    fprintf("[traj_eval_analysis] predicted radial sigma mean=%.3f m | error/sigma median=%.3f\n", ...
        analysis.covariance.mean_predicted_radial_sigma_m, ...
        analysis.covariance.normalized_position_error.median);
end
fprintf("\n");

if cfg.save_outputs
    metrics_table = build_metrics_table(analysis, reference, samples, analysis_mask);
    metrics_csv_path = fullfile(output_dir, "analysis_metrics.csv");
    writetable(metrics_table, metrics_csv_path);

    report_path = fullfile(output_dir, "analysis_report.txt");
    write_analysis_report(report_path, analysis, reference, samples_csv_path, session_dir);

    save(fullfile(output_dir, "analysis_result.mat"), ...
        "analysis", "reference", "samples", "analysis_mask", "metrics_table");
end

%% Plots
fig_map = plot_map_analysis(samples, analysis_mask, reference, anchors, analysis, cfg);
fig_diag = plot_diagnostics(samples, analysis_mask, analysis);

if cfg.save_outputs
    save_figure(fig_map, fullfile(output_dir, "analysis_map.png"));
    save_figure(fig_diag, fullfile(output_dir, "analysis_diagnostics.png"));
    fprintf("[traj_eval_analysis] saved analysis outputs to %s\n", output_dir);
end

%% Local functions
function [samples_csv_path, session_dir] = resolve_samples_csv_path(cfg)
    if strlength(cfg.samples_csv_path) > 0
        samples_csv_path = char(cfg.samples_csv_path);
        if exist(samples_csv_path, "file") ~= 2
            error("[traj_eval_analysis] samples_csv_path not found: %s", samples_csv_path);
        end
        session_dir = fileparts(samples_csv_path);
        return;
    end

    if strlength(cfg.session_dir) > 0
        session_dir = char(cfg.session_dir);
        samples_csv_path = fullfile(session_dir, "samples.csv");
        if exist(samples_csv_path, "file") ~= 2
            error("[traj_eval_analysis] samples.csv not found in session_dir: %s", session_dir);
        end
        return;
    end

    logs_root_dir = char(cfg.logs_root_dir);
    if exist(logs_root_dir, "dir") ~= 7
        error("[traj_eval_analysis] logs folder not found: %s", logs_root_dir);
    end

    d = dir(logs_root_dir);
    best_datenum = -Inf;
    best_dir = "";
    for i = 1:numel(d)
        if ~d(i).isdir || strcmp(d(i).name, ".") || strcmp(d(i).name, "..")
            continue;
        end
        candidate_dir = fullfile(logs_root_dir, d(i).name);
        candidate_csv = fullfile(candidate_dir, "samples.csv");
        if exist(candidate_csv, "file") == 2 && d(i).datenum > best_datenum
            best_datenum = d(i).datenum;
            best_dir = candidate_dir;
        end
    end

    if strlength(best_dir) == 0
        error("[traj_eval_analysis] no TRAJ_EVAL session with samples.csv found in %s", logs_root_dir);
    end

    session_dir = char(best_dir);
    samples_csv_path = fullfile(session_dir, "samples.csv");
end

function reference = load_reference_definition(session_dir, samples)
    metadata_path = fullfile(session_dir, "metadata.txt");
    if exist(metadata_path, "file") == 2
        txt = fileread(metadata_path);
        p0 = [parse_metadata_number(txt, "start_x_m"), parse_metadata_number(txt, "start_y_m")];
        p1 = [parse_metadata_number(txt, "end_x_m"), parse_metadata_number(txt, "end_y_m")];
        node0 = parse_metadata_number(txt, "anchor_start_node_id");
        node1 = parse_metadata_number(txt, "anchor_end_node_id");
        if all(isfinite([p0, p1]))
            if isfinite(node0) && isfinite(node1)
                label = sprintf("node %.0f -> node %.0f", node0, node1);
            else
                label = "metadata reference";
            end
            reference = build_reference(p0, p1, label);
            return;
        end
    end

    required = ["closest_rect_x_m", "closest_rect_y_m", "along_track_m"];
    if all(ismember(required, string(samples.Properties.VariableNames)))
        ok = isfinite(samples.closest_rect_x_m) & isfinite(samples.closest_rect_y_m) & ...
             isfinite(samples.along_track_m);
        if nnz(ok) >= 2
            [~, i0_rel] = min(samples.along_track_m(ok));
            [~, i1_rel] = max(samples.along_track_m(ok));
            idx = find(ok);
            p0 = [samples.closest_rect_x_m(idx(i0_rel)), samples.closest_rect_y_m(idx(i0_rel))];
            p1 = [samples.closest_rect_x_m(idx(i1_rel)), samples.closest_rect_y_m(idx(i1_rel))];
            reference = build_reference(p0, p1, "closest-point fallback reference");
            fprintf("[traj_eval_analysis] metadata missing; inferred reference from closest_rect columns.\n");
            return;
        end
    end

    error("[traj_eval_analysis] Could not determine ideal rectilinear reference from metadata or samples.");
end

function value = parse_metadata_number(txt, key)
    expr = sprintf('%s,([^\\r\\n]+)', regexptranslate('escape', char(key)));
    tok = regexp(txt, expr, "tokens", "once");
    if isempty(tok)
        value = NaN;
    else
        value = str2double(tok{1});
    end
end

function reference = build_reference(p0, p1, label)
    ref_vec = p1(:).' - p0(:).';
    length_m = norm(ref_vec);
    if length_m <= 1e-9
        error("[traj_eval_analysis] Ideal reference endpoints are coincident.");
    end

    reference = struct();
    reference.points_xy = [p0(:).'; p1(:).'];
    reference.unit_xy = ref_vec ./ length_m;
    reference.length_m = length_m;
    reference.heading_rad = atan2(ref_vec(2), ref_vec(1));
    reference.label = char(label);
end

function anchors = load_dept_map_anchors(map_csv_path)
    anchors = table();
    if exist(map_csv_path, "file") ~= 2
        fprintf("[traj_eval_analysis] map CSV not found; map plot will omit anchors: %s\n", map_csv_path);
        return;
    end

    try
        map = readtable(map_csv_path, 'VariableNamingRule', 'preserve');
    catch
        map = readtable(map_csv_path);
    end

    names = string(map.Properties.VariableNames);
    node_col = find_table_column(names, ["NodeId", "node_id", "nodeid", "node", "id"]);
    x_col = find_table_column(names, ["x", "X", "lat", "Lat", "latitude", "Latitude", "px", "pos_x"]);
    y_col = find_table_column(names, ["y", "Y", "lon", "Lon", "longitude", "Longitude", "py", "pos_y"]);
    coord_col = find_table_column(names, ["Coordinates", "coordinates", "coord", "coords", "xy", "position"]);

    if node_col > 0
        node_id = parse_numeric_column(map.(char(names(node_col))));
    else
        node_id = (1:height(map)).';
    end

    if x_col > 0 && y_col > 0
        x = parse_numeric_column(map.(char(names(x_col))));
        y = parse_numeric_column(map.(char(names(y_col))));
    elseif coord_col > 0
        [x, y] = parse_coordinate_column(map.(char(names(coord_col))));
    else
        [node_id, x, y, ok_fallback] = infer_headerless_map_columns(map, node_id);
        if ~ok_fallback
            fprintf("[traj_eval_analysis] map CSV has no recognizable coordinate columns. Columns are: %s\n", ...
                strjoin(names, ", "));
            return;
        end
    end

    valid = isfinite(x) & isfinite(y);
    anchors = table(node_id(valid), x(valid), y(valid), ...
        'VariableNames', {'node_id', 'x', 'y'});
end

function [node_id, x, y, ok] = infer_headerless_map_columns(map, default_node_id)
%INFER_HEADERLESS_MAP_COLUMNS Handle maps imported as Var1, Var2, ...
% Common cases:
% - Var1=node_id, Var2=zone, Var3="[x", Var4="y]" because coordinates were
%   not quoted.
% - Var1=node_id, Var2=x, Var3=y or similar plain numeric exports.
    ok = false;
    node_id = default_node_id(:);
    x = NaN(height(map), 1);
    y = NaN(height(map), 1);
    names = string(map.Properties.VariableNames);

    if numel(names) < 2
        return;
    end

    numeric_cols = NaN(height(map), numel(names));
    numeric_score = zeros(1, numel(names));
    for i = 1:numel(names)
        numeric_cols(:, i) = parse_numeric_column_loose(map.(char(names(i))));
        numeric_score(i) = nnz(isfinite(numeric_cols(:, i)));
    end

    % Prefer node ids from the first mostly-numeric column.
    node_candidates = find(numeric_score >= max(2, 0.5 * height(map)));
    if ~isempty(node_candidates)
        node_id = numeric_cols(:, node_candidates(1));
    end

    % Case: one Var column contains the whole text "[x, y]".
    for i = 1:numel(names)
        [x_i, y_i] = parse_coordinate_column(map.(char(names(i))));
        if nnz(isfinite(x_i) & isfinite(y_i)) >= max(2, 0.5 * height(map))
            x = x_i;
            y = y_i;
            ok = true;
            return;
        end
    end

    % Case: node_id, zone, x, y split from an unquoted "[x, y]" field.
    if numel(names) >= 4
        x3 = parse_numeric_column_loose(map.(char(names(3))));
        y4 = parse_numeric_column_loose(map.(char(names(4))));
        if nnz(isfinite(x3) & isfinite(y4)) >= max(2, 0.5 * height(map))
            x = x3;
            y = y4;
            ok = true;
            return;
        end
    end

    % Same split-coordinate case, but do not assume the pair starts at Var3.
    for i = 1:(numel(names) - 1)
        x_i = parse_numeric_column_loose(map.(char(names(i))));
        y_i = parse_numeric_column_loose(map.(char(names(i + 1))));
        if nnz(isfinite(x_i) & isfinite(y_i)) >= max(2, 0.5 * height(map))
            % Avoid using the same column as node id when a later pair is available.
            if ~isempty(node_candidates) && i == node_candidates(1) && i + 2 <= numel(names)
                continue;
            end
            x = x_i;
            y = y_i;
            ok = true;
            return;
        end
    end

    % Case: plain numeric columns; choose the first plausible coordinate pair
    % after the node id column.
    coord_candidates = find(numeric_score >= max(2, 0.5 * height(map)));
    if numel(coord_candidates) >= 3
        x = numeric_cols(:, coord_candidates(2));
        y = numeric_cols(:, coord_candidates(3));
        ok = true;
    elseif numel(coord_candidates) >= 2
        x = numeric_cols(:, coord_candidates(1));
        y = numeric_cols(:, coord_candidates(2));
        ok = true;
    end
end

function idx = find_table_column(names, aliases)
    idx = 0;
    norm_names = normalize_column_names(names);
    norm_aliases = normalize_column_names(aliases);
    for i = 1:numel(norm_aliases)
        hit = find(norm_names == norm_aliases(i), 1);
        if ~isempty(hit)
            idx = hit;
            return;
        end
    end
end

function out = normalize_column_names(values)
    out = lower(regexprep(string(values), "[^a-zA-Z0-9]", ""));
end

function values = parse_numeric_column(col)
    if isnumeric(col)
        values = double(col);
    else
        values = str2double(string(col));
    end
    values = values(:);
end

function values = parse_numeric_column_loose(col)
    if isnumeric(col)
        values = double(col);
        values = values(:);
        return;
    end

    txt = string(col);
    txt = regexprep(txt, '[^0-9eE+\-\.]', '');
    values = str2double(txt);
    values = values(:);
end

function [x, y] = parse_coordinate_column(coord_col)
    coord_text = string(coord_col);
    coord_text = erase(coord_text, "[");
    coord_text = erase(coord_text, "]");
    parts = split(coord_text, ",");
    if size(parts, 2) < 2
        x = NaN(numel(coord_text), 1);
        y = NaN(numel(coord_text), 1);
        return;
    end
    x = str2double(strtrim(parts(:,1)));
    y = str2double(strtrim(parts(:,2)));
end

function mask = build_analysis_mask(samples, cfg)
    names = string(samples.Properties.VariableNames);
    require_names = ["est_x_m", "est_y_m"];
    if ~all(ismember(require_names, names))
        error("[traj_eval_analysis] samples.csv must contain est_x_m and est_y_m.");
    end

    mask = isfinite(samples.est_x_m) & isfinite(samples.est_y_m);

    if cfg.use_only_samples_projected_inside_segment && ismember("projection_clamped", names)
        mask = mask & (samples.projection_clamped == 0);
    end

    if ismember("rect_fraction", names) && numel(cfg.keep_rect_fraction_range) == 2
        f0 = min(cfg.keep_rect_fraction_range);
        f1 = max(cfg.keep_rect_fraction_range);
        mask = mask & samples.rect_fraction >= f0 & samples.rect_fraction <= f1;
    end
end

function analysis = analyze_trajectory(samples, mask, reference)
    xy = [samples.est_x_m(mask), samples.est_y_m(mask)];
    geom = project_points_to_reference(xy, reference);
    error_xy = xy - geom.closest_xy;
    ref_u = reference.unit_xy(:).';

    analysis = struct();
    analysis.sample_count = size(xy, 1);
    analysis.xy = xy;
    analysis.error_xy_m = error_xy;
    analysis.reference_projection = geom;
    analysis.distance_to_segment_m = vector_stats(geom.distance_to_segment_m);
    analysis.position_error_m = analysis.distance_to_segment_m;
    analysis.error_x_m = vector_stats(error_xy(:,1));
    analysis.error_y_m = vector_stats(error_xy(:,2));
    analysis.along_endpoint_error_m = vector_stats(error_xy * ref_u(:));
    analysis.signed_cross_track_m = vector_stats(geom.signed_cross_track_m);
    analysis.abs_cross_track_m = vector_stats(abs(geom.signed_cross_track_m));
    analysis.along_track_m = vector_stats(geom.along_track_m);
    analysis.rect_fraction = vector_stats(geom.fraction);
    analysis.coverage_fraction_span = max(geom.fraction) - min(geom.fraction);
    analysis.est_x_m = vector_stats(xy(:,1));
    analysis.est_y_m = vector_stats(xy(:,2));
    analysis.xy_covariance_m2 = cov(xy);
    analysis.path = compute_path_metrics(xy, geom, reference);
    analysis.timing = compute_timing_metrics(samples, mask, analysis.path.path_length_m);
    analysis.covariance = compute_covariance_scale_diagnostic(samples, mask, error_xy);
    analysis.ols = fit_ordinary_least_squares_line(xy, reference);
    analysis.tls = fit_total_least_squares_line(xy, reference);
end

function geom = project_points_to_reference(xy, reference)
    p0 = reference.points_xy(1,:);
    u = reference.unit_xy(:).';
    rel = xy - p0;
    along_unclamped = rel * u(:);
    fraction_unclamped = along_unclamped ./ reference.length_m;
    fraction = min(max(fraction_unclamped, 0.0), 1.0);
    along = fraction .* reference.length_m;
    closest = p0 + along .* u;

    geom = struct();
    geom.closest_xy = closest;
    geom.along_track_m = along;
    geom.unclamped_along_track_m = along_unclamped;
    geom.fraction = fraction;
    geom.fraction_unclamped = fraction_unclamped;
    geom.projection_clamped = fraction ~= fraction_unclamped;
    geom.distance_to_segment_m = sqrt(sum((xy - closest).^2, 2));
    geom.signed_cross_track_m = u(1) .* rel(:,2) - u(2) .* rel(:,1);
end

function fit = fit_ordinary_least_squares_line(xy, reference)
    x = xy(:,1);
    y = xy(:,2);
    x_range = max(x) - min(x);
    y_range = max(y) - min(y);

    fit = struct();
    fit.model = "y_on_x";
    fit.beta = [NaN; NaN];
    fit.heading_rad = NaN;
    fit.heading_error_deg = NaN;
    fit.r2 = NaN;
    fit.residual = NaN(size(x));
    fit.line_xy = [NaN, NaN; NaN, NaN];

    if x_range >= max(1e-9, 0.25 * y_range)
        A = [ones(numel(x), 1), x];
        beta = A \ y;
        y_hat = A * beta;
        residual = y - y_hat;
        sse = sum(residual.^2);
        sst = sum((y - mean(y)).^2);
        theta = atan2(beta(2), 1.0);

        x_line = linspace(min([x; reference.points_xy(:,1)]), max([x; reference.points_xy(:,1)]), 2).';
        y_line = beta(1) + beta(2) .* x_line;
        fit.line_xy = [x_line, y_line];
    else
        fit.model = "x_on_y";
        A = [ones(numel(y), 1), y];
        beta = A \ x;
        x_hat = A * beta;
        residual = x - x_hat;
        sse = sum(residual.^2);
        sst = sum((x - mean(x)).^2);
        theta = atan2(1.0, beta(2));

        y_line = linspace(min([y; reference.points_xy(:,2)]), max([y; reference.points_xy(:,2)]), 2).';
        x_line = beta(1) + beta(2) .* y_line;
        fit.line_xy = [x_line, y_line];
    end

    fit.beta = beta;
    fit.heading_rad = choose_axis_heading_direction(theta, reference.heading_rad);
    fit.heading_error_deg = rad2deg(axis_heading_error(fit.heading_rad, reference.heading_rad));
    if sst > 1e-12
        fit.r2 = 1.0 - sse / sst;
    end
    fit.residual = residual;
    fit.residual_stats = vector_stats(residual);
end

function fit = fit_total_least_squares_line(xy, reference)
    mu = mean(xy, 1);
    centered = xy - mu;
    C = centered.' * centered / max(size(centered, 1) - 1, 1);
    [V, D] = eig(0.5 * (C + C.'));
    [~, idx] = max(diag(D));
    direction = V(:, idx).';
    direction = direction ./ max(norm(direction), 1e-12);

    theta = atan2(direction(2), direction(1));
    theta = choose_axis_heading_direction(theta, reference.heading_rad);
    direction = [cos(theta), sin(theta)];
    normal = [-direction(2), direction(1)];
    residual = (xy - mu) * normal(:);

    t_xy = (xy - mu) * direction(:);
    t_ref = (reference.points_xy - mu) * direction(:);
    t_min = min([t_xy; t_ref]);
    t_max = max([t_xy; t_ref]);
    pad = 0.05 * max(t_max - t_min, 1.0);
    t_line = [t_min - pad; t_max + pad];

    fit = struct();
    fit.center_xy = mu;
    fit.direction_xy = direction;
    fit.heading_rad = theta;
    fit.heading_error_deg = rad2deg(axis_heading_error(theta, reference.heading_rad));
    fit.orthogonal_residual = residual;
    fit.orthogonal_residual_m = vector_stats(residual);
    fit.line_xy = mu + t_line .* direction;
end

function path = compute_path_metrics(xy, geom, reference)
    path = struct();
    path.path_length_m = NaN;
    path.net_displacement_m = NaN;
    path.ideal_covered_length_m = NaN;
    path.ideal_total_length_m = reference.length_m;
    path.coverage_fraction_span = NaN;
    path.path_length_ratio_to_ideal_covered = NaN;
    path.straightness_ratio = NaN;
    path.sinuosity_ratio = NaN;
    path.progress_direction = 0;
    path.backtrack_step_count = 0;
    path.backtrack_distance_m = 0;
    path.overshoot_before_start_m = NaN;
    path.overshoot_after_end_m = NaN;

    if size(xy, 1) < 2
        return;
    end

    steps = sqrt(sum(diff(xy, 1, 1).^2, 2));
    path.path_length_m = sum(steps, 'omitnan');
    path.net_displacement_m = norm(xy(end,:) - xy(1,:));

    f_min = min(geom.fraction, [], 'omitnan');
    f_max = max(geom.fraction, [], 'omitnan');
    path.coverage_fraction_span = max(f_max - f_min, 0);
    path.ideal_covered_length_m = path.coverage_fraction_span * reference.length_m;

    if path.ideal_covered_length_m > 1e-9
        path.path_length_ratio_to_ideal_covered = path.path_length_m / path.ideal_covered_length_m;
    end
    if path.path_length_m > 1e-9
        path.straightness_ratio = path.net_displacement_m / path.path_length_m;
    end
    if path.net_displacement_m > 1e-9
        path.sinuosity_ratio = path.path_length_m / path.net_displacement_m;
    end

    along = geom.unclamped_along_track_m;
    direction = sign(along(end) - along(1));
    if direction == 0
        direction = 1;
    end
    progress_delta = direction * diff(along);
    backtrack = progress_delta < 0;
    path.progress_direction = direction;
    path.backtrack_step_count = nnz(backtrack);
    path.backtrack_distance_m = sum(abs(progress_delta(backtrack)), 'omitnan');
    path.overshoot_before_start_m = max(0, -min(along, [], 'omitnan'));
    path.overshoot_after_end_m = max(0, max(along, [], 'omitnan') - reference.length_m);
end

function timing = compute_timing_metrics(samples, mask, path_length_m)
    timing = struct();
    timing.available = false;
    timing.duration_s = NaN;
    timing.effective_update_rate_hz = NaN;
    timing.sample_period_s = vector_stats([]);
    timing.sample_period_jitter_s = NaN;
    timing.mean_speed_mps = NaN;

    names = string(samples.Properties.VariableNames);
    t = [];
    if ismember("time_s", names)
        t = double(samples.time_s(mask));
    elseif ismember("relative_round_idx", names)
        t = double(samples.relative_round_idx(mask));
    end
    t = t(:);
    t = t(isfinite(t));
    if numel(t) < 2
        return;
    end

    dt = diff(t);
    dt = dt(isfinite(dt) & dt > 0);
    if isempty(dt)
        return;
    end

    timing.available = true;
    timing.duration_s = max(t) - min(t);
    if timing.duration_s > 0
        timing.effective_update_rate_hz = (numel(t) - 1) / timing.duration_s;
        timing.mean_speed_mps = path_length_m / timing.duration_s;
    end
    timing.sample_period_s = vector_stats(dt);
    timing.sample_period_jitter_s = timing.sample_period_s.std;
end

function cov_eval = compute_covariance_scale_diagnostic(samples, mask, error_xy)
    cov_eval = struct();
    cov_eval.available = false;
    cov_eval.sample_count = 0;
    cov_eval.position_error_values_m = [];
    cov_eval.predicted_radial_sigma_values_m = [];
    cov_eval.predicted_radial_sigma_all_m = [];
    cov_eval.normalized_position_error_values = [];
    cov_eval.normalized_position_error = vector_stats([]);
    cov_eval.mean_predicted_sigma_x_m = NaN;
    cov_eval.mean_predicted_sigma_y_m = NaN;
    cov_eval.mean_predicted_radial_sigma_m = NaN;

    names = string(samples.Properties.VariableNames);
    required = ["cov_xx_m2", "cov_yy_m2", "cov_xy_m2"];
    if ~all(ismember(required, names))
        return;
    end

    cov_xx = double(samples.cov_xx_m2(mask));
    cov_yy = double(samples.cov_yy_m2(mask));
    cov_xy = double(samples.cov_xy_m2(mask));
    norm_err = NaN(size(cov_xx));
    pos_err = sqrt(sum(error_xy.^2, 2));
    sigma_x = sqrt(max(cov_xx, 0));
    sigma_y = sqrt(max(cov_yy, 0));
    sigma_radial = sqrt(max(cov_xx + cov_yy, 0));
    cov_eval.predicted_radial_sigma_all_m = sigma_radial;

    for i = 1:numel(cov_xx)
        P = [cov_xx(i), cov_xy(i); cov_xy(i), cov_yy(i)];
        P = 0.5 * (P + P.');
        e = error_xy(i,:).';
        if any(~isfinite(P(:))) || any(~isfinite(e)) || rcond(P) < 1e-12
            continue;
        end
        if sigma_radial(i) > 1e-12
            norm_err(i) = pos_err(i) / sigma_radial(i);
        end
    end

    valid = isfinite(norm_err);
    if ~any(valid)
        return;
    end

    cov_eval.available = true;
    cov_eval.sample_count = nnz(valid);
    cov_eval.position_error_values_m = pos_err(valid);
    cov_eval.predicted_radial_sigma_values_m = sigma_radial(valid);
    cov_eval.normalized_position_error_values = norm_err(isfinite(norm_err));
    cov_eval.normalized_position_error = vector_stats(norm_err(isfinite(norm_err)));
    cov_eval.mean_predicted_sigma_x_m = mean(sigma_x(isfinite(sigma_x)), 'omitnan');
    cov_eval.mean_predicted_sigma_y_m = mean(sigma_y(isfinite(sigma_y)), 'omitnan');
    cov_eval.mean_predicted_radial_sigma_m = mean(sigma_radial(isfinite(sigma_radial)), 'omitnan');
end

function s = vector_stats(x)
    x = x(:);
    x = x(isfinite(x));
    s = struct("n", numel(x), "mean", NaN, "std", NaN, "var", NaN, ...
        "rmse", NaN, "mae", NaN, "median", NaN, "p50", NaN, ...
        "p75", NaN, "p90", NaN, "p95", NaN, "p99", NaN, ...
        "ci95_half_width", NaN, "ci95_low", NaN, "ci95_high", NaN, ...
        "min", NaN, "max", NaN);
    if isempty(x)
        return;
    end
    s.mean = mean(x);
    s.std = std(x);
    s.var = var(x);
    s.rmse = sqrt(mean(x.^2));
    s.mae = mean(abs(x));
    s.median = median(x);
    s.p50 = percentile_no_toolbox(abs(x), 50);
    s.p75 = percentile_no_toolbox(abs(x), 75);
    s.p90 = percentile_no_toolbox(abs(x), 90);
    s.p95 = percentile_no_toolbox(abs(x), 95);
    s.p99 = percentile_no_toolbox(abs(x), 99);
    if s.n > 1
        s.ci95_half_width = 1.96 * s.std / sqrt(s.n);
        s.ci95_low = s.mean - s.ci95_half_width;
        s.ci95_high = s.mean + s.ci95_half_width;
    end
    s.min = min(x);
    s.max = max(x);
end

function p = percentile_no_toolbox(x, pct)
    x = sort(x(:));
    x = x(isfinite(x));
    n = numel(x);
    if n == 0
        p = NaN;
        return;
    end
    if n == 1
        p = x(1);
        return;
    end
    q = min(max(pct / 100.0, 0.0), 1.0);
    pos = 1 + (n - 1) * q;
    lo = floor(pos);
    hi = ceil(pos);
    if lo == hi
        p = x(lo);
    else
        p = x(lo) + (pos - lo) * (x(hi) - x(lo));
    end
end

function metrics_table = build_metrics_table(analysis, reference, samples, mask)
    rows = {};
    rows = add_metric(rows, "selected_sample_count", analysis.sample_count, "count");
    rows = add_metric(rows, "logged_sample_count", height(samples), "count");
    rows = add_metric(rows, "ideal_length_m", reference.length_m, "m");
    rows = add_metric(rows, "ideal_heading_deg", rad2deg(reference.heading_rad), "deg");
    rows = add_metric(rows, "coverage_fraction_span", analysis.coverage_fraction_span, "fraction");

    rows = add_stats_metrics(rows, "position_error_to_ideal_segment", analysis.position_error_m, "m");
    rows = add_stats_metrics(rows, "distance_to_ideal_segment", analysis.distance_to_segment_m, "m");
    rows = add_stats_metrics(rows, "axis_error_x", analysis.error_x_m, "m");
    rows = add_stats_metrics(rows, "axis_error_y", analysis.error_y_m, "m");
    rows = add_stats_metrics(rows, "along_endpoint_error", analysis.along_endpoint_error_m, "m");
    rows = add_stats_metrics(rows, "signed_cross_track", analysis.signed_cross_track_m, "m");
    rows = add_stats_metrics(rows, "abs_cross_track", analysis.abs_cross_track_m, "m");
    rows = add_stats_metrics(rows, "tls_orthogonal_residual", analysis.tls.orthogonal_residual_m, "m");

    rows = add_metric(rows, "ols_heading_error_deg", analysis.ols.heading_error_deg, "deg");
    rows = add_metric(rows, "ols_r2", analysis.ols.r2, "unitless");
    rows = add_metric(rows, "ols_residual_std", analysis.ols.residual_stats.std, "model_units");
    rows = add_metric(rows, "tls_heading_error_deg", analysis.tls.heading_error_deg, "deg");
    rows = add_metric(rows, "xy_cov_xx_m2", analysis.xy_covariance_m2(1,1), "m2");
    rows = add_metric(rows, "xy_cov_yy_m2", analysis.xy_covariance_m2(2,2), "m2");
    rows = add_metric(rows, "xy_cov_xy_m2", analysis.xy_covariance_m2(1,2), "m2");

    rows = add_metric(rows, "path_length_m", analysis.path.path_length_m, "m");
    rows = add_metric(rows, "net_displacement_m", analysis.path.net_displacement_m, "m");
    rows = add_metric(rows, "ideal_covered_length_m", analysis.path.ideal_covered_length_m, "m");
    rows = add_metric(rows, "path_length_ratio_to_ideal_covered", analysis.path.path_length_ratio_to_ideal_covered, "unitless");
    rows = add_metric(rows, "path_straightness_ratio", analysis.path.straightness_ratio, "unitless");
    rows = add_metric(rows, "path_sinuosity_ratio", analysis.path.sinuosity_ratio, "unitless");
    rows = add_metric(rows, "backtrack_step_count", analysis.path.backtrack_step_count, "count");
    rows = add_metric(rows, "backtrack_distance_m", analysis.path.backtrack_distance_m, "m");
    rows = add_metric(rows, "overshoot_before_start_m", analysis.path.overshoot_before_start_m, "m");
    rows = add_metric(rows, "overshoot_after_end_m", analysis.path.overshoot_after_end_m, "m");

    rows = add_metric(rows, "duration_s", analysis.timing.duration_s, "s");
    rows = add_metric(rows, "effective_update_rate_hz", analysis.timing.effective_update_rate_hz, "Hz");
    rows = add_metric(rows, "mean_speed_mps", analysis.timing.mean_speed_mps, "m/s");
    rows = add_stats_metrics(rows, "sample_period", analysis.timing.sample_period_s, "s");

    if analysis.covariance.available
        rows = add_metric(rows, "covariance_sample_count", analysis.covariance.sample_count, "count");
        rows = add_stats_metrics(rows, "position_error_over_predicted_radial_sigma", analysis.covariance.normalized_position_error, "unitless");
        rows = add_metric(rows, "mean_predicted_sigma_x_m", analysis.covariance.mean_predicted_sigma_x_m, "m");
        rows = add_metric(rows, "mean_predicted_sigma_y_m", analysis.covariance.mean_predicted_sigma_y_m, "m");
        rows = add_metric(rows, "mean_predicted_radial_sigma_m", analysis.covariance.mean_predicted_radial_sigma_m, "m");
    end

    names = string(samples.Properties.VariableNames);
    if ismember("round_id", names)
        round_ids = samples.round_id(mask);
        round_ids = round_ids(isfinite(round_ids));
        if ~isempty(round_ids)
            rows = add_metric(rows, "round_id_first", min(round_ids), "round");
            rows = add_metric(rows, "round_id_last", max(round_ids), "round");
        end
    end
    if ismember("relative_round_idx", names)
        rel = samples.relative_round_idx(mask);
        rel = rel(isfinite(rel));
        if ~isempty(rel)
            rows = add_metric(rows, "relative_round_first", min(rel), "round");
            rows = add_metric(rows, "relative_round_last", max(rel), "round");
        end
    end

    metric = string(rows(:,1));
    value = cell2mat(rows(:,2));
    unit = string(rows(:,3));
    metrics_table = table(metric, value, unit, ...
        'VariableNames', {'metric', 'value', 'unit'});
end

function rows = add_stats_metrics(rows, prefix, s, unit)
    rows = add_metric(rows, prefix + "_n", s.n, "count");
    rows = add_metric(rows, prefix + "_mean", s.mean, unit);
    rows = add_metric(rows, prefix + "_std", s.std, unit);
    rows = add_metric(rows, prefix + "_var", s.var, unit + "2");
    rows = add_metric(rows, prefix + "_rmse", s.rmse, unit);
    rows = add_metric(rows, prefix + "_mae", s.mae, unit);
    rows = add_metric(rows, prefix + "_median", s.median, unit);
    rows = add_metric(rows, prefix + "_p50_abs", s.p50, unit);
    rows = add_metric(rows, prefix + "_p75_abs", s.p75, unit);
    rows = add_metric(rows, prefix + "_p90_abs", s.p90, unit);
    rows = add_metric(rows, prefix + "_p95_abs", s.p95, unit);
    rows = add_metric(rows, prefix + "_p99_abs", s.p99, unit);
    rows = add_metric(rows, prefix + "_mean_ci95_half_width", s.ci95_half_width, unit);
    rows = add_metric(rows, prefix + "_mean_ci95_low", s.ci95_low, unit);
    rows = add_metric(rows, prefix + "_mean_ci95_high", s.ci95_high, unit);
    rows = add_metric(rows, prefix + "_min", s.min, unit);
    rows = add_metric(rows, prefix + "_max", s.max, unit);
end

function rows = add_metric(rows, name, value, unit)
    rows(end+1, :) = {char(name), value, char(unit)};
end

function write_analysis_report(report_path, analysis, reference, samples_csv_path, session_dir)
    fid = fopen(report_path, "w");
    if fid < 0
        fprintf("[traj_eval_analysis] warning: could not write report %s\n", report_path);
        return;
    end
    cleaner = onCleanup(@() fclose(fid));

    fprintf(fid, "TRAJ_EVAL linear-regression analysis\n");
    fprintf(fid, "session_dir: %s\n", session_dir);
    fprintf(fid, "samples_csv: %s\n", samples_csv_path);
    fprintf(fid, "ideal_reference: %s\n", reference.label);
    fprintf(fid, "ideal_start_xy_m: %.6f, %.6f\n", reference.points_xy(1,1), reference.points_xy(1,2));
    fprintf(fid, "ideal_end_xy_m: %.6f, %.6f\n", reference.points_xy(2,1), reference.points_xy(2,2));
    fprintf(fid, "ideal_length_m: %.6f\n", reference.length_m);
    fprintf(fid, "ideal_heading_deg: %.6f\n", rad2deg(reference.heading_rad));
    fprintf(fid, "selected_samples: %d\n\n", analysis.sample_count);

    fprintf(fid, "reference_metrics_basis\n");
    fprintf(fid, "  HMM/UWB tracking papers: position RMSE over trajectory.\n");
    fprintf(fid, "  GPS-vs-UWB athlete tracking: MAE, SD, median, RMSE, CI, CDF percentiles.\n");
    fprintf(fid, "  UWB LT systems: average positioning error, MAE, standard deviation, latency/update-rate effects.\n");
    fprintf(fid, "  DTDoA/distributed UWB: axis-wise mean error, standard deviation, uncertainty and dynamic trajectory tests.\n");

    print_stats(fid, "distance_to_ideal_segment_m", analysis.distance_to_segment_m);
    print_stats(fid, "axis_error_x_m", analysis.error_x_m);
    print_stats(fid, "axis_error_y_m", analysis.error_y_m);
    print_stats(fid, "along_endpoint_error_m", analysis.along_endpoint_error_m);
    print_stats(fid, "signed_cross_track_m", analysis.signed_cross_track_m);
    print_stats(fid, "abs_cross_track_m", analysis.abs_cross_track_m);
    print_stats(fid, "tls_orthogonal_residual_m", analysis.tls.orthogonal_residual_m);

    fprintf(fid, "\npath_quality\n");
    fprintf(fid, "  path_length_m: %.9f\n", analysis.path.path_length_m);
    fprintf(fid, "  net_displacement_m: %.9f\n", analysis.path.net_displacement_m);
    fprintf(fid, "  ideal_covered_length_m: %.9f\n", analysis.path.ideal_covered_length_m);
    fprintf(fid, "  path_length_ratio_to_ideal_covered: %.9f\n", analysis.path.path_length_ratio_to_ideal_covered);
    fprintf(fid, "  straightness_ratio: %.9f\n", analysis.path.straightness_ratio);
    fprintf(fid, "  sinuosity_ratio: %.9f\n", analysis.path.sinuosity_ratio);
    fprintf(fid, "  backtrack_step_count: %.0f\n", analysis.path.backtrack_step_count);
    fprintf(fid, "  backtrack_distance_m: %.9f\n", analysis.path.backtrack_distance_m);
    fprintf(fid, "  overshoot_before_start_m: %.9f\n", analysis.path.overshoot_before_start_m);
    fprintf(fid, "  overshoot_after_end_m: %.9f\n", analysis.path.overshoot_after_end_m);

    fprintf(fid, "\ntiming_update_rate\n");
    fprintf(fid, "  available: %.0f\n", analysis.timing.available);
    fprintf(fid, "  duration_s: %.9f\n", analysis.timing.duration_s);
    fprintf(fid, "  effective_update_rate_hz: %.9f\n", analysis.timing.effective_update_rate_hz);
    fprintf(fid, "  mean_speed_mps: %.9f\n", analysis.timing.mean_speed_mps);
    print_stats(fid, "sample_period_s", analysis.timing.sample_period_s);

    fprintf(fid, "\ncovariance_scale_diagnostic\n");
    fprintf(fid, "  available: %.0f\n", analysis.covariance.available);
    fprintf(fid, "  sample_count: %.0f\n", analysis.covariance.sample_count);
    fprintf(fid, "  mean_predicted_sigma_x_m: %.9f\n", analysis.covariance.mean_predicted_sigma_x_m);
    fprintf(fid, "  mean_predicted_sigma_y_m: %.9f\n", analysis.covariance.mean_predicted_sigma_y_m);
    fprintf(fid, "  mean_predicted_radial_sigma_m: %.9f\n", analysis.covariance.mean_predicted_radial_sigma_m);
    fprintf(fid, "  note: ratio uses closest point on the ideal segment, not time-aligned ground truth.\n");
    print_stats(fid, "position_error_over_predicted_radial_sigma", analysis.covariance.normalized_position_error);

    fprintf(fid, "\nordinary_least_squares\n");
    fprintf(fid, "  model: %s\n", char(analysis.ols.model));
    fprintf(fid, "  beta0: %.9f\n", analysis.ols.beta(1));
    fprintf(fid, "  beta1: %.9f\n", analysis.ols.beta(2));
    fprintf(fid, "  heading_deg: %.9f\n", rad2deg(analysis.ols.heading_rad));
    fprintf(fid, "  heading_error_deg: %.9f\n", analysis.ols.heading_error_deg);
    fprintf(fid, "  r2: %.9f\n", analysis.ols.r2);

    fprintf(fid, "\ntotal_least_squares\n");
    fprintf(fid, "  heading_deg: %.9f\n", rad2deg(analysis.tls.heading_rad));
    fprintf(fid, "  heading_error_deg: %.9f\n", analysis.tls.heading_error_deg);
    fprintf(fid, "  residual_std_m: %.9f\n", analysis.tls.orthogonal_residual_m.std);
    fprintf(fid, "  residual_rmse_m: %.9f\n", analysis.tls.orthogonal_residual_m.rmse);
end

function print_stats(fid, label, s)
    fprintf(fid, "\n%s\n", label);
    fprintf(fid, "  n: %.0f\n", s.n);
    fprintf(fid, "  mean: %.9f\n", s.mean);
    fprintf(fid, "  std: %.9f\n", s.std);
    fprintf(fid, "  var: %.9f\n", s.var);
    fprintf(fid, "  rmse: %.9f\n", s.rmse);
    fprintf(fid, "  mae: %.9f\n", s.mae);
    fprintf(fid, "  median: %.9f\n", s.median);
    fprintf(fid, "  p50_abs: %.9f\n", s.p50);
    fprintf(fid, "  p75_abs: %.9f\n", s.p75);
    fprintf(fid, "  p90_abs: %.9f\n", s.p90);
    fprintf(fid, "  p95_abs: %.9f\n", s.p95);
    fprintf(fid, "  p99_abs: %.9f\n", s.p99);
    fprintf(fid, "  mean_ci95_half_width: %.9f\n", s.ci95_half_width);
    fprintf(fid, "  mean_ci95_low: %.9f\n", s.ci95_low);
    fprintf(fid, "  mean_ci95_high: %.9f\n", s.ci95_high);
    fprintf(fid, "  min: %.9f\n", s.min);
    fprintf(fid, "  max: %.9f\n", s.max);
end

function fig = plot_map_analysis(samples, mask, reference, anchors, analysis, cfg)
    xy = analysis.xy;
    geom = analysis.reference_projection;

    fig = figure("Name", "TRAJ_EVAL map analysis", "Color", "w");
    hold on; grid on; axis equal;

    if ~isempty(anchors) && height(anchors) > 0
        plot(anchors.x, anchors.y, "bo", "MarkerSize", 7, "LineWidth", 1.0, ...
            "DisplayName", "Anchors");
    end

    estimated_green = [0.00, 0.95, 0.25];
    estimated_green_edge = [0.00, 0.45, 0.12];
    ideal_dark_green = [0.00, 0.28, 0.08];

    plot(reference.points_xy(:,1), reference.points_xy(:,2), "--", ...
        "Color", ideal_dark_green, "LineWidth", 1.2, ...
        "DisplayName", "Ideal rectilinear trajectory");
    plot(reference.points_xy(:,1), reference.points_xy(:,2), "ks", ...
        "MarkerFaceColor", [1.0, 0.9, 0.15], "MarkerSize", 8, ...
        "DisplayName", "Ideal endpoints");

    plot(xy(:,1), xy(:,2), "-", "Color", estimated_green, ...
        "LineWidth", 1.0, "DisplayName", "Estimated path");
    scatter(xy(:,1), xy(:,2), 30, "filled", ...
        "MarkerFaceColor", estimated_green, ...
        "MarkerEdgeColor", estimated_green_edge, ...
        "DisplayName", "Estimated samples");

    plot(geom.closest_xy(:,1), geom.closest_xy(:,2), ".", ...
        "Color", [0.95, 0.55, 0.05], "MarkerSize", 9, ...
        "DisplayName", "Closest ideal points");

    if cfg.plot_residual_segments_on_map
        idx = residual_plot_indices(size(xy, 1), cfg.max_residual_segments_on_map);
        for i = idx(:).'
            plot([xy(i,1), geom.closest_xy(i,1)], [xy(i,2), geom.closest_xy(i,2)], ...
                "-", "Color", [0.95, 0.70, 0.35], "HandleVisibility", "off");
        end
    end

    plot(analysis.ols.line_xy(:,1), analysis.ols.line_xy(:,2), ...
        "-", "Color", [0.05, 0.35, 0.95], "LineWidth", 2.0, ...
        "DisplayName", "OLS regression");
    plot(analysis.tls.line_xy(:,1), analysis.tls.line_xy(:,2), ...
        "-", "Color", [0.80, 0.10, 0.70], "LineWidth", 2.0, ...
        "DisplayName", "TLS orthogonal fit");

    xlabel("X [m]");
    ylabel("Y [m]");
    title(sprintf("TRAJ_EVAL map | dist RMSE %.3f m | std %.3f m | TLS heading err %.2f deg", ...
        analysis.distance_to_segment_m.rmse, analysis.distance_to_segment_m.std, ...
        analysis.tls.heading_error_deg));
    legend("Location", "best");
end

function fig = plot_diagnostics(samples, mask, analysis)
    [x_axis, x_label] = diagnostic_x_axis(samples, mask);
    geom = analysis.reference_projection;
    [cdf_x, cdf_y] = empirical_cdf(geom.distance_to_segment_m);
    [abs_cross_cdf_x, abs_cross_cdf_y] = empirical_cdf(abs(geom.signed_cross_track_m));
    [x_axis, sort_idx] = sort_diagnostic_axis(x_axis);
    signed_cross_plot = geom.signed_cross_track_m(sort_idx);
    distance_plot = geom.distance_to_segment_m(sort_idx);

    fig = figure("Name", "TRAJ_EVAL diagnostics", "Color", "w");

    subplot(2,3,1);
    plot(x_axis, signed_cross_plot, "-o", "LineWidth", 1.2, "MarkerSize", 3);
    hold on; grid on;
    xl = xlim;
    plot(xl, [0, 0], "k--", "LineWidth", 1.0);
    xlabel(x_label);
    ylabel("Signed cross-track [m]");
    title("Signed lateral error vs sample");

    subplot(2,3,2);
    plot(geom.fraction, geom.distance_to_segment_m, ".", "MarkerSize", 10);
    grid on;
    xlabel("Ideal segment fraction");
    ylabel("Distance to ideal segment [m]");
    title("Distance along ideal trajectory");

    subplot(2,3,3);
    plot(cdf_x, cdf_y, "LineWidth", 1.5);
    hold on; grid on;
    plot(abs_cross_cdf_x, abs_cross_cdf_y, "LineWidth", 1.5);
    xlabel("Error magnitude [m]");
    ylabel("Empirical CDF");
    title("Error CDF");
    legend("Position error", "Abs cross-track", "Location", "southeast");

    subplot(2,3,4);
    histogram(geom.signed_cross_track_m, 30);
    grid on;
    xlabel("Signed cross-track [m]");
    ylabel("Count");
    title("Cross-track distribution");

    subplot(2,3,5);
    histogram(abs(geom.signed_cross_track_m), 30);
    grid on;
    xlabel("Absolute cross-track [m]");
    ylabel("Count");
    title("Absolute error distribution");

    subplot(2,3,6);
    if analysis.covariance.available
        pred_all = analysis.covariance.predicted_radial_sigma_all_m;
        if numel(pred_all) == numel(sort_idx)
            pred_sigma = pred_all(sort_idx);
        else
            pred_sigma = NaN(size(distance_plot));
        end
        plot(x_axis, distance_plot, "LineWidth", 1.3);
        hold on; grid on;
        plot(x_axis, pred_sigma, "LineWidth", 1.3);
        xlabel(x_label);
        ylabel("Magnitude [m]");
        title("Error vs covariance scale");
        legend("Reference-line error", "Predicted radial 1-sigma", "Location", "best");
    else
        text(0.5, 0.5, "No covariance columns", "HorizontalAlignment", "center");
        axis off;
        title("Error vs covariance scale");
    end
end

function [x_axis, x_label] = diagnostic_x_axis(samples, mask)
    names = string(samples.Properties.VariableNames);
    if ismember("time_s", names)
        x_axis = double(samples.time_s(mask));
        if any(isfinite(x_axis)) && max(x_axis, [], 'omitnan') > min(x_axis, [], 'omitnan')
            x_label = "Time [s]";
            return;
        end
    end

    if ismember("sample_idx", names)
        x_axis = double(samples.sample_idx(mask));
        if any(isfinite(x_axis))
            x_label = "Sample index";
            return;
        end
    end

    x_axis = (0:nnz(mask)-1).';
    x_label = "Sample index";
end

function [x_sorted, sort_idx] = sort_diagnostic_axis(x_axis)
    x_axis = double(x_axis(:));
    if all(~isfinite(x_axis))
        x_axis = (0:numel(x_axis)-1).';
    else
        bad = ~isfinite(x_axis);
        x_axis(bad) = find(bad) - 1;
    end
    [x_sorted, sort_idx] = sort(x_axis);
end

function [x_sorted, cdf_y] = empirical_cdf(x)
    x_sorted = sort(x(:));
    x_sorted = x_sorted(isfinite(x_sorted));
    n = numel(x_sorted);
    if n == 0
        x_sorted = NaN;
        cdf_y = NaN;
        return;
    end
    cdf_y = (1:n).' ./ n;
end

function values = sample_color_values(samples, mask)
    names = string(samples.Properties.VariableNames);
    if ismember("relative_round_idx", names)
        values = samples.relative_round_idx(mask);
    elseif ismember("sample_idx", names)
        values = samples.sample_idx(mask);
    else
        values = (0:nnz(mask)-1).';
    end
    values = double(values);
    if all(~isfinite(values))
        values = (0:numel(values)-1).';
    else
        bad = ~isfinite(values);
        values(bad) = find(bad) - 1;
    end
end

function idx = residual_plot_indices(n, max_count)
    if n <= 0
        idx = [];
        return;
    end
    max_count = max(1, round(max_count));
    if n <= max_count
        idx = 1:n;
    else
        idx = unique(round(linspace(1, n, max_count)));
    end
end

function save_figure(fig, output_path)
    try
        exportgraphics(fig, output_path, "Resolution", 180);
    catch
        saveas(fig, output_path);
    end
end

function theta_sel = choose_axis_heading_direction(theta_axis_raw, theta_ref)
    theta_a = wrap_angle_pi(theta_axis_raw);
    theta_b = wrap_angle_pi(theta_axis_raw + pi);
    if abs(wrap_angle_pi(theta_a - theta_ref)) <= abs(wrap_angle_pi(theta_b - theta_ref))
        theta_sel = theta_a;
    else
        theta_sel = theta_b;
    end
end

function err = axis_heading_error(theta, theta_ref)
    err = wrap_angle_pi(theta - theta_ref);
    if err > pi/2
        err = err - pi;
    elseif err < -pi/2
        err = err + pi;
    end
end

function ang = wrap_angle_pi(ang)
    ang = mod(ang + pi, 2*pi) - pi;
end
